import{_ as a,a0 as r,w as O,s as o,I as t,x as i,a1 as n,A as p,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse(`{"title":"是時候合併 LibreOffice 和 OpenOffice 了 | LCTT x X-CMD","titleTemplate":false,"description":"是時候合併 LibreOffice 和 OpenOffice 了 | LCTT (201609) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"是時候合併 LibreOffice 和 OpenOffice 了 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"是時候合併 LibreOffice 和 OpenOffice 了 | LCTT (201609) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201609/20160914 It's time to make LibreOffice and OpenOffice one again","title":"是時候合併 LibreOffice 和 OpenOffice 了","tag":"201609","desc":""},"relativePath":"201609/20160914 It's time to make LibreOffice and OpenOffice one again.md","filePath":"[post].md"}`),c={name:"201609/20160914 It's time to make LibreOffice and OpenOffice one again.md"};function s(b,e,d,m,L,u){const f=r("Link");return O(),o("div",null,[e[18]||(e[18]=t("h1",{id:"是時候合併-libreoffice-和-openoffice-了",tabindex:"-1"},[i("是時候合併 LibreOffice 和 OpenOffice 了 "),t("a",{class:"header-anchor",href:"#是時候合併-libreoffice-和-openoffice-了","aria-label":"Permalink to “是時候合併 LibreOffice 和 OpenOffice 了”"},"​")],-1)),e[19]||(e[19]=t("p",null,[t("img",{src:"http://tr2.cbsistatic.com/hub/i/2016/09/14/2e91089b-7ebd-4579-bf8f-74c34d1a94ce/e7e9c8dd481d8e068f2934c644788928/openofficedeathhero.jpg",alt:""})],-1)),t("p",null,[e[2]||(e[2]=i("先説下 OpenOffice。可能你已經無數次地看到説 Apache OpenOffice 即將結束。上一個穩定版本是 4.1.2 （發佈於 2015 年 10 月），而最近的一個嚴重安全漏洞用了一個月才打上補丁。編碼人員的缺乏使得開發如爬行前進一般。然後，可能是最糟糕的消息了：這個項目建議用户切換到 ",-1)),n(f,{href:"https://products.office.com/"},{default:p(()=>[...e[0]||(e[0]=[i("MS Office",-1)])]),_:1}),e[3]||(e[3]=i("（或 ",-1)),n(f,{href:"https://www.libreoffice.org/download/"},{default:p(()=>[...e[1]||(e[1]=[i("LibreOffice",-1)])]),_:1}),e[4]||(e[4]=i(")。",-1))]),e[20]||(e[20]=l('<p>喪鐘為誰而鳴？喪鐘為你而鳴，OpenOffice。</p><p>我想説些可能會惹惱一些人的話。你準備好了嗎？</p><p>OpenOffice 的終止對開源和用户來説都將是件好事。</p><p>讓我解釋一下。</p><h3 id="一個分支統治所有" tabindex="-1">一個分支統治所有 <a class="header-anchor" href="#一個分支統治所有" aria-label="Permalink to “一個分支統治所有”">​</a></h3><p>當 LibreOffice 從 OpenOffice 分支出來後，我們看到了另一個情況：分支不只在原始基礎上進行改進，而且大幅超越了它。LibreOffice 一舉成功。所有之前預裝 OpenOffice 的 Linux 發行版都遷移到了這個新項目。LibreOffice 從起跑線突然衝出，並迅速邁出了一大步。更新以極快的速度發佈，改善內容豐富而重要。</p><p>不久後，OpenOffice 就被開源社區丟在了腦後。當 2011 年 Oracle 決定終止這個項目並把代碼捐贈給 Apache 項目時，這種情況自然更加惡化了。從此 OpenOffice 艱難前進，然後把我們就看到了現在這種局面：一個生機勃勃的 LibreOffice 和一個艱難的、緩慢的 OpenOffice。</p><p>但我認為在這個相當昏暗的隧道末尾有一絲曙光。</p><h3 id="合併他們" tabindex="-1">合併他們 <a class="header-anchor" href="#合併他們" aria-label="Permalink to “合併他們”">​</a></h3><p>這聽起來可能很瘋狂，但我認為是時候把 LibreOffice 和 OpenOffice 合二為一了。是的，我知道很可能有政治考慮和自尊意識，但我認為合併成一個會更好。合併的好處很多。我首先能想到的是：</p><ul><li>把 MS Office 過濾器整合起來：OpenOffice 在更好地導入某些 MS Office 文件上功能很強（而眾所周知 LibreOffice 正在改進，但時好時壞）</li><li>LibreOffice 有更多開發者：儘管 OpenOffice 的開發者數量不多，但也無疑會增加到合併後的項目。</li><li>結束混亂：很多用户以為 OpenOffice 和 LibreOffice 是同一個東西。有些甚至不知道 LibreOffice 存在。這將終結那些混亂。</li><li>合併他們的用户量：OpenOffice 和 LibreOffice 各自擁有大量用户。聯合後，他們將是個巨大的力量。</li></ul><h3 id="寶貴機遇" tabindex="-1">寶貴機遇 <a class="header-anchor" href="#寶貴機遇" aria-label="Permalink to “寶貴機遇”">​</a></h3><p>OpenOffice 的終止實際上會成為整個開源辦公套件行業的一個寶貴機遇。為什麼？我想表明有些東西我認為已經需要很久了。如果 OpenOffice 和 LibreOffice 集中他們的力量，比較他們的代碼併合並，他們之後就可以做一些更必要的改進工作，不僅是整體的內部工作，也包括界面。</p><p>我們得面對現實，LibreOffice 和（相關的） OpenOffice 的用户界面都是過時的。當我安裝 LibreOffice 5.2.1.2 時，工具欄絕對是個災難（見下圖）。</p><p><img src="http://tr2.cbsistatic.com/hub/i/2016/09/14/cc5250df-48cd-40e3-a083-34250511ffab/c5ac8eb1e2cb12224690a6a3525999f0/openofficea.jpg" alt=""></p><p><em>LibreOffice 默認工具欄顯示</em></p><p>儘管我支持和關心（並且日常使用）LibreOffice，但事實已經再清楚不過了，界面需要完全重寫。我們正在使用的是 90 年代末/ 2000 年初的復古界面，它必須得改變了。當新用户第一次打開 LibreOffice 時，他們會被淹沒在大量按鈕、圖標和工具欄中。Ubuntu Unity 的平視顯示（Head up Display，簡稱 HUD）幫助解決了這個問題，但那並不適用於其它桌面和發行版。當然，有經驗的用户知道在哪裏找什麼（甚至定製工具欄以滿足特殊的需要），但對新用户或普通用户，那種界面是個噩夢。現在是做出改變的一個好時機。引入 OpenOffice 最後殘留的開發者並讓他們加入到改善界面的戰鬥中。藉助於整合 OpenOffice 額外的導入過濾器和現代化的界面，LibreOffice 終能在家庭和辦公桌面上都引起一些轟動。</p><h3 id="這會真的發生嗎" tabindex="-1">這會真的發生嗎？ <a class="header-anchor" href="#這會真的發生嗎" aria-label="Permalink to “這會真的發生嗎？”">​</a></h3><p>這需要發生。但是會發生嗎？我不知道。但即使掌權者決定用户界面並不需要重組（這會是個失誤），合併 OpenOffice 仍是前進的一大步。合併兩者將帶來開發的更專注，更好的推廣，公眾更少的困惑。</p><p>我知道這可能看起來有悖於開源的核心精神，但合併 LibreOffice 和 OpenOffice 將能聯合兩者的力量，而且可能會擺脱弱點。</p><p>在我看來，這是雙贏的。</p><hr>',22)),t("p",null,[e[6]||(e[6]=i("via: ",-1)),n(f,{href:"http://www.techrepublic.com/article/its-time-to-make-libreoffice-and-openoffice-one-again/"},{default:p(()=>[...e[5]||(e[5]=[i("http://www.techrepublic.com/article/its-time-to-make-libreoffice-and-openoffice-one-again/",-1)])]),_:1})]),t("p",null,[e[10]||(e[10]=i("作者：",-1)),n(f,{href:"http://www.techrepublic.com/search/?a=jack%2Bwallen"},{default:p(()=>[...e[7]||(e[7]=[i("Jack Wallen",-1)])]),_:1}),e[11]||(e[11]=i(" 譯者：",-1)),n(f,{href:"https://github.com/bianjp"},{default:p(()=>[...e[8]||(e[8]=[i("bianjp",-1)])]),_:1}),e[12]||(e[12]=i(" 校對：",-1)),n(f,{href:"https://github.com/wxy"},{default:p(()=>[...e[9]||(e[9]=[i("wxy",-1)])]),_:1})]),t("p",null,[e[15]||(e[15]=i("本文由 ",-1)),n(f,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[13]||(e[13]=[i("LCTT",-1)])]),_:1}),e[16]||(e[16]=i(" 原創編譯，",-1)),n(f,{href:"https://linux.cn/"},{default:p(()=>[...e[14]||(e[14]=[i("Linux中國",-1)])]),_:1}),e[17]||(e[17]=i(" 榮譽推出",-1))])])}const x=a(c,[["render",s]]);export{g as __pageData,x as default};
